/*
  # Competitive pricing model + customizer add-ons (seed)

  Seeds the CMS `site_content` overrides so the LIVE site matches the new code
  defaults, even where an admin had previously saved older content.

  - `pricing`: four tiers — Starter, Essential, Professional (fixed prices,
    shown without GST) and Custom (quote-based). Audiobook lines removed.
  - `customizer`: add-on model (baseCost 0), realistic GSM-based paper and
    real binding/cover/layout options with plain-language descriptions, and a
    de-duplicated questionnaire (cover-concept and trim-size questions removed,
    since the Cover Design and Book Size selectors already cover them).

  Idempotent: re-running upserts the same values.
*/

INSERT INTO site_content (key, value, updated_at) VALUES
('pricing', '{"heading": "Publishing Plans for Every Author", "subheading": "Choose the perfect package for your publishing journey. All plans include professional quality and industry-standard services.", "plans": [{"name": "Starter", "price": "₹24,999", "tagline": "Everything a first-time author needs to publish", "popular": false, "royaltyRate": 30, "features": ["Professional copyediting (up to 50,000 words)", "Basic proofreading", "Pre-designed cover template customization", "Standard interior formatting (black & white)", "ISBN assignment", "Copyright registration assistance", "Distribution to Amazon & major online retailers", "Author copies (5 paperback copies)", "Basic book description optimization", "Email support", "Cursive Classics imprint"]}, {"name": "Essential", "price": "₹49,999", "tagline": "For authors ready to build a brand", "popular": true, "royaltyRate": 45, "features": ["Comprehensive developmental editing", "Professional copyediting (up to 100,000 words)", "Multiple rounds of proofreading", "Custom cover design (3 concepts)", "Premium interior formatting (colour available)", "ISBN & Barcode", "Copyright registration (full service)", "Wide distribution (Amazon, Flipkart, libraries)", "Author copies (15 copies in mixed formats)", "Professional book description & metadata", "Press release (2 versions)", "Marketing toolkit (social media graphics, bookmarks)", "Author website (single page)", "Launch strategy consultation", "Cursive Imprint Series imprint", "Priority support (phone & email)"]}, {"name": "Professional", "price": "₹89,999", "tagline": "Premium publishing with full marketing support", "popular": false, "royaltyRate": 55, "features": ["Comprehensive developmental editing", "Professional copyediting (unlimited words)", "Multiple rounds of proofreading & fact-checking", "Premium custom cover design (5 concepts)", "Luxury interior formatting with custom elements", "Multiple ISBNs (hardcover, paperback, ebook)", "Copyright & trademark registration", "Global + Indian distribution (40+ platforms)", "Author copies (30 copies in all formats)", "Professional book description & metadata optimization", "Comprehensive press kit (3 press releases)", "Full marketing suite (social media, email templates)", "Professional author website (5 pages)", "Video book trailer (60-90 seconds)", "Professional author photography session", "Launch campaign management (3 months)", "Amazon & Flipkart Ads setup", "Cursive Prestige imprint", "Dedicated account manager", "Priority support (24/7 access)"]}, {"name": "Custom", "price": "Custom", "tagline": "Tailored to your book — let''s build your package", "popular": false, "royaltyRate": 60, "features": ["Everything in Professional, tailored to your goals", "Full developmental & structural editing", "Unlimited cover concepts by senior designers", "Premium interior design by award-winning designers", "Multiple ISBNs (all formats)", "Full copyright & trademark protection", "Bespoke marketing & ad-campaign planning", "Custom author website & brand assets", "Dedicated account manager", "Priced to scope — request a tailored quote"]}], "imprintsHeading": "About Our Imprints", "imprints": [{"name": "Cursive Classics (Starter Plan)", "desc": "Our foundational imprint for emerging authors. Perfect for traditional fiction, memoirs, and first-time publications that will be printed with our classic, timeless aesthetic."}, {"name": "Cursive Imprint Series (Essential Plan)", "desc": "For authors building their brand and creating professional, market-competitive titles across all genres. This imprint signifies quality and editorial excellence."}, {"name": "Cursive Prestige (Professional Plan)", "desc": "Reserved for authors published at the highest standards. Your imprint will feature on premium-quality books with exclusive design elements and premium distribution."}, {"name": "Cursive Signature (Custom Plan)", "desc": "Our most exclusive imprint featuring the author''s biography and signature edition mark. Only for authors receiving our fully bespoke, white-glove publishing service."}]}'::jsonb, now()),
('customizer', '{"heading": "Design Your Book", "subheading": "Customize every aspect of your book production and get real-time price estimates. See exactly what you''re getting before you commit.", "baseCost": 0, "paperTypes": [{"id": "std70", "name": "70 GSM Natural Shade", "desc": "Standard novel paper. Light cream shade that is easy on the eyes for long reading — the everyday choice for fiction & non-fiction.", "price": 0}, {"id": "white80", "name": "80 GSM White", "desc": "Bright white and a touch thicker. A crisp, clean look for textbooks, workbooks and business books.", "price": 200}, {"id": "cream90", "name": "90 GSM Premium Cream", "desc": "Heavier, more luxurious cream stock with a refined feel. Popular for premium hardbacks and gift editions.", "price": 600}, {"id": "art130", "name": "130 GSM Art Paper", "desc": "Smooth, coated paper made for sharp photos and full-colour pages. Best for photo, art and children’s books.", "price": 1200}], "colorOptions": [{"id": "bw", "name": "Black & White", "desc": "Single-colour interior printing — the standard, most affordable choice for text-only books.", "price": 0}, {"id": "color", "name": "Full Colour", "desc": "Every page printed in full colour. Needed for photos, illustrations and colour charts.", "price": 2500}], "bindingOptions": [{"id": "paperback", "name": "Paperback (Softback)", "desc": "A flexible card cover — lighter, cheaper and the most common choice. “Softback” and “paperback” mean the same thing.", "price": 0}, {"id": "hardback", "name": "Hardback (Hardcover)", "desc": "A stiff board cover — more durable and premium, and it stays looking good for years. Ideal for gifts and keepsakes.", "price": 1500}], "coverDesigns": [{"id": "standard", "name": "Standard Cover", "desc": "A clean, professionally laid-out cover. Included at no extra cost.", "price": 0}, {"id": "matte", "name": "Matte Lamination", "desc": "A soft, non-glare finish that feels premium and resists fingerprints.", "price": 500}, {"id": "gloss", "name": "Gloss Lamination", "desc": "A shiny finish that makes cover colours pop — great for commercial fiction.", "price": 500}, {"id": "embossed", "name": "Embossed / Spot UV", "desc": "Raised or spot-gloss title and elements you can actually feel — a premium bookstore look.", "price": 2000}, {"id": "foil", "name": "Foil Stamping", "desc": "Metallic gold or silver accents stamped onto the cover for a luxury, gift-worthy finish.", "price": 3500}], "layoutOptions": [{"id": "single", "name": "Single Column", "desc": "The classic book layout — one clean column of text. Right for almost all novels and non-fiction.", "price": 0}, {"id": "double", "name": "Two Column", "desc": "Two columns of text per page — compact and modern. Common in academic and reference books.", "price": 1000}, {"id": "illustrated", "name": "Illustrated Layout", "desc": "Text designed around images, art and captions. Built for photo, art and children’s books.", "price": 3000}, {"id": "custom", "name": "Custom Design", "desc": "A unique interior designed from scratch for your book by our team.", "price": 5000}], "bookSizes": [{"id": "demy", "name": "Demy", "desc": "Classic novel / fiction size", "price": 0, "pb": {"w": 140, "l": 215, "win": 5.5, "lin": 8.5}, "hb": {"w": 145, "l": 222, "win": 5.7, "lin": 8.75}}, {"id": "crown1", "name": "Crown1", "desc": "Compact non-fiction", "price": 0, "pb": {"w": 170, "l": 240, "win": 6.75, "lin": 9.5}, "hb": {"w": 174, "l": 240, "win": 6.85, "lin": 9.5}}, {"id": "royal", "name": "Royal", "desc": "Popular all-rounder", "price": 0, "pb": {"w": 160, "l": 240, "win": 6.25, "lin": 9.5}, "hb": {"w": 163, "l": 248, "win": 6.4, "lin": 9.75}}, {"id": "crown", "name": "Crown", "desc": "Wider trim, textbooks", "price": 0, "pb": {"w": 185, "l": 235, "win": 7.25, "lin": 9.25}, "hb": {"w": 188, "l": 248, "win": 7.4, "lin": 9.75}}, {"id": "doubledemy", "name": "Double Demy", "desc": "Coffee-table / photo books", "price": 0, "pb": {"w": 215, "l": 280, "win": 8.5, "lin": 11}, "hb": {"w": 220, "l": 285, "win": 8.7, "lin": 11.25}}], "questionnaireEnabled": true, "questions": [{"id": "genre", "text": "What genre best describes your book?", "type": "text", "placeholder": "e.g. Literary fiction, memoir, self-help…"}, {"id": "reader", "text": "Who do you picture as your ideal reader?", "type": "text", "placeholder": "e.g. Young professionals, new parents…"}, {"id": "wordCount", "text": "What''s your manuscript''s approximate word count?", "type": "number", "placeholder": "e.g. 65000", "options": [{"id": "under40k", "label": "Under 40,000 words", "minValue": 0, "priceImpact": 0}, {"id": "40to80k", "label": "40,000–80,000 words", "minValue": 40000, "priceImpact": 0}, {"id": "80to120k", "label": "80,000–120,000 words", "minValue": 80000, "priceImpact": 300}, {"id": "over120k", "label": "Over 120,000 words", "minValue": 120000, "priceImpact": 600}]}, {"id": "images", "text": "Will your book include photos, illustrations, or charts?", "type": "choice", "options": [{"id": "none", "label": "No images", "priceImpact": 0}, {"id": "few", "label": "A few (under 10)", "priceImpact": 200}, {"id": "many", "label": "Many (10+) / heavy illustration", "priceImpact": 800}]}, {"id": "printRun", "text": "Is this a one-time print run, or do you plan to reprint as it sells?", "type": "choice", "options": [{"id": "onetime", "label": "One-time print run", "priceImpact": 0}, {"id": "reprint", "label": "Plan to reprint as it sells", "priceImpact": 0}]}, {"id": "timeline", "text": "What''s your target launch timeline?", "type": "choice", "options": [{"id": "standard", "label": "Standard (8–10 weeks)", "priceImpact": 0}, {"id": "rush", "label": "Rush — I need it sooner", "priceImpact": 1000}]}, {"id": "channel", "text": "Will you sell mainly in print, eBook, or both?", "type": "choice", "options": [{"id": "print", "label": "Mainly print", "priceImpact": 0}, {"id": "ebook", "label": "Mainly eBook", "priceImpact": 0}, {"id": "both", "label": "Both print and eBook", "priceImpact": 500}]}]}'::jsonb, now())
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
